				{ type = "quest", id = 1444 },
			},
			text = [=[A scout brought him a sentence of judgment, written in blood on dried flesh. It named a priest of the Atal'ai condemned to exile among the {link:witherbark-trolls}Witherbark trolls{/link} of the {link:the-hinterlands}Hinterlands{/link}. Fel'zerul sent the relics to that exile. The answer that came back was grave. The relics were harmless, the exile said. But the high priest {link:jammal-an-the-prophet}Jammal'an{/link} had a prophecy, and if he had found the right enchantment for his fetishes, the whole world lay in peril.]=],
		},
		{
			key = "the-fetishes-of-hakkar",
			title = "The Fetishes of Hakkar",
			hint = [=[Enter the drowned temple and seize the fetishes of the Atal'ai.]=],
			unlock = {
				{ type = "quest", id = 1445 },
			},
			text = [=[{link:jammal-an-the-prophet}Jammal'an the Prophet{/link} believes that when {link:hakkar}Hakkar{/link} returns, the god will give the Atal'ai eternal life. Fel'zerul calls it a trick that will bring doom before its time. He does not fear the prophecy so much as the fetishes that might fulfill it. He sent champions of the {link:horde}Horde{/link} down into the temple to take them. When they returned with the fetishes in hand, he named them champions of the Horde.]=],
		},
	},
	mentions = {
