Add({
	kind = "figure",
	id = "fallen-hero-of-the-horde",
	title = "Fallen Hero of the Horde",
	aliases = { "Fallen Hero" },
	subtitle = "Spirit of the Swamp",
	tier = "B",
	region = "swamp-of-sorrows",
	npc = { 7572 },
	allegiance = "Horde (once)",
	found = [=[The southern edge of the swamp, beside the road to the Blasted Lands]=],
	pin = { x = 34.3, y = 66.1 },
	unlock = {
		{ type = "interact" },
	},
	hint = "Seek the restless spirit who waits beside the southern road.",
	sections = {
		{
			title = "Summary",
			text = [=[Near the road that leads south into the {link:blasted-lands}Blasted Lands{/link} stands the ghost of a warrior of the {link:horde}Horde{/link}. In life he commanded a regiment called {link:thrall}Thrall{/link}'s Grasp. He led it into the Blasted Lands without waiting for his orders, and the regiment was destroyed. Now he stands where he fell, still waiting for orders that never came. He cannot strike a blow himself. He can only ask the living for help, and he asks warriors of the {link:alliance}Alliance{/link} and the Horde alike.]=],
		},
		{
			title = "Significance",
			text = [=[The Fallen Hero bears witness to a war that most of the world has forgotten. Beyond the {link:dark-portal}Dark Portal{/link}'s ruins, demons still rule the {link:blasted-lands}Blasted Lands{/link} under a lord called {link:razelikh-the-defiler}Razelikh the Defiler{/link}. The Fallen Hero knows this better than anyone living. He teaches that the true enemy is not the {link:alliance}Alliance{/link} or the {link:horde}Horde{/link}, but the Legion that waits for both.]=],
		},
		{
			title = "Deeds",
			text = [=[• He led the regiment {link:thrall}Thrall{/link}'s Grasp into the {link:blasted-lands}Blasted Lands{/link} before his orders reached him.
• He calls on the living to free the souls of his men and to break the demon lord's power.
• He welcomes the {link:alliance}Alliance{/link} to fight beside the {link:horde}Horde{/link} against the demons.
• He tests warriors of every people and rewards those who prove worthy.]=],
		},
		{
			title = "Unrecorded",
			text = [=[Nothing is written of this warrior's life before {link:thrall}Thrall{/link}'s Grasp was sent south. Whether Trebor was his own name, {link:kirith-the-damned}Kirith{/link}'s spirit did not make plain.]=],
		},
	},
	chapters = {
		{
			key = "the-missing-orders",
			title = "The Missing Orders",
			hint = [=[Learn what became of the orders the fallen commander never received.]=],
			unlock = {
				{ type = "quest", id = 2623 },
			},
			text = [=[In death he could think only of the orders. {link:dispatch-commander-ruag}Dispatch Commander Ruag{/link} of {link:stonard}Stonard{/link} swore that he had sent them. His riders were ambushed by murlocs on the road, and only one of them lived. That survivor, {link:bengor}Bengor{/link}, could barely speak. He said that a {link:murlocs}murloc{/link} called the {link:swamp-talker}Swamp Talker{/link} tore the orders from his hands and fled east to a cave. The Fallen Hero learned that his men need not have died. Nineteen of them might have been spared, if only he had waited.]=],
		},
		{
			key = "the-stones-that-bind",
			title = "The Stones That Bind",
			hint = [=[Free the souls of the fallen regiment from the stones of the Blasted Lands.]=],
			unlock = {
				{ type = "quest", id = 2681 },
			},
			text = [=[The demons did not let the soldiers of {link:thrall}Thrall{/link}'s Grasp rest. Their souls were bound into stones scattered across the {link:blasted-lands}Blasted Lands{/link}, eighteen in all. Only when the stones were broken could the men find peace. When the last one shattered, the Fallen Hero knew that his long debt had begun to be repaid.]=],
		},
		{
			key = "the-lost-lieutenant",
			title = "The Lost Lieutenant",
			hint = "Seek the fate of the one lieutenant who was never found.",
			unlock = {
				{ type = "quest", id = 2721 },
			},
			text = [=[One of his officers was still missing. {link:kirith-the-damned}Lieutenant Kirith{/link} had been imprisoned and tortured beside him in the caves of a demon named {link:archmage-allistarj}Allistarj{/link}, but Kirith's will had broken under the torture. The Fallen Hero heard his screams from his own cage, and then heard nothing more. When at last Kirith's spirit was found, it answered with a name: Trebor.]=],
		},
		{
			key = "the-defiler",
			title = "The Defiler",
			hint = [=[Unite the shattered amulet and face the demon lord of the Blasted Lands.]=],
			unlock = {
				{ type = "quest", id = 3628 },
			},
			text = [=[{link:razelikh-the-defiler}Razelikh the Defiler{/link} ruled the {link:blasted-lands}Blasted Lands{/link} through three servants. Each wore a third of an amulet, and while they held it they could not die within the demon's lands. The Fallen Hero sent his champions to break the three and join the amulet whole, and then to climb to the demon's lair on the highest peak. When the Defiler fell, the Fallen Hero asked for his horn. He meant it to be proof that heroes still live in a world broken by war.]=],
		},
	},
	mentions = {
		{
			text = "Fall From Grace",
			unlock = {
				{ type = "quest", id = 2784 },
			},
		},
		{
