	},
	hint = "Find the human prisoner held in Stonard.",
	sections = {
		{
			title = "Summary",
			text = [=[Marksen is a human spy of the {link:alliance}Alliance{/link}, caught near the Forsaken camp at {link:beggar-s-haunt}Beggar's Haunt{/link} and held prisoner in {link:stonard}Stonard{/link}. He has not been allowed a drink in days. He begs for mercy and claims to hold secrets that reach beyond the Alliance itself: treachery at high levels that, he says, must be brought to light. The {link:forsaken}Forsaken{/link} want those secrets, and they do not mean to ask politely.]=],
		},
		{
			title = "Significance",
			text = [=[Marksen's secret links {link:stonard}Stonard{/link} to the hidden quarrels of the kingdoms. What he knows, and who else knows it, is not recorded.]=],
