	},
	chapters = {
		{
			key = "nothing-but-the-truth",
			title = "Nothing But the Truth",
			hint = "Bring the prisoner of Stonard a drink from the Forsaken.",
			unlock = {
				{ type = "quest", id = 1391 },
			},
			text = [=[The {link:forsaken}Forsaken{/link} apothecary Faustin brewed a serum to loosen a man's tongue, and the Deathstalker Zraedus mixed it into a cup of ale. A cup of ale was the one thing the thirsty prisoner would not refuse. Marksen drank it down gladly and began to speak.]=],
		},
	},
